WITH latest AS (SELECT id, store_name, city, region, opened_date, sqft FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY region, city ORDER BY opened_date DESC NULLS LAST, id) AS rank_in_group FROM stores) t WHERE rank_in_group = 1) SELECT DATE_TRUNC('WEEK', opened_date) AS week_start, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count, SORT_ARRAY(COLLECT_SET(region)) AS region_list FROM latest GROUP BY DATE_TRUNC('WEEK', opened_date) HAVING bangkok_count > 1;
